		# (不带头结点)插入x作为第i个元素
		p = self.head
		j = -1
		while p is not None and j < i-1:
			p = p.next
			j += 1
		if j>i-1 or p is None:
			raise Exception("插入位置不合法")
		s = Node(data=x)
		if i==0:
			s.next = self.head
		else:
			s.next = p.next
			p.next = s
	'''

	def remove(self,i):
		'''删除第i个元素'''
		p = self.head
		j = -1
		# 寻找第i个结点的前驱结点
		while p is not None and j<i-1:
			p = p.next
			j += 1
		if j>i-1 or p.next is None:
			raise Exception("删除位置不合法")
		p.next = p.next.next

	def indexOf(self,x):
		'''返回元素x首次出现的位序号'''
		p = self.head.next
		j = 0
		while p is not None and not (p.data == x):
			p = p.next
			j += 1
		if p is not None:
			return j
		else:
			return -1

	def display(self):
		'''输出线性表中各个数据元素的值'''
		p = self.head.next
		while p is not None:
			print(p.data,end=' ')
			p = p.next

