	def __init__(self,a,i):
		self.a = a # 系数
		self.i = i # 指数

def add(p1,p2):
	L = LinkList()
	i = j = 0
	while i<p1.length() and j<p2.length():
		x,y = p1.get(i),p2.get(j)
		if x.i==y.i:
			L.insert(L.length(),PloyNode(x.a+y.a,x.i))
			i += 1
			j += 1
		elif x.i>y.i:
			L.insert(L.length(),PloyNode(x.a,x.i))
			i += 1
		else:
			L.insert(L.length(),PloyNode(y.a,y.i))
			j += 1
	while i<p1.length():
		x = p1.get(i)
		L.insert(L.length(),PloyNode(x.a,x.i))
		i += 1
	while j<p2.length():
		y = p2.get(j)
		L.insert(L.length(),PloyNode(y.a,y.i))
		j += 1
	return L


