def plusOne(digits):
    n = len(digits)
    for i in range(n - 1, -1, -1):
        if digits[i] != 9:
            digits[i] += 1
            for j in range(i + 1, n):
                digits[j] = 0
            return digits
    return [1] + [0] * n

