def pruneTree(self, root):
    if root is None:
        return None
    root.lchild = self.pruneTree(root.lchild)
    root.rchild = self.pruneTree(root.rchild)
    if root.lchild is None and root.rchild is None and root.data == 0:
        return None
    return root

def isSameTree(self, p, q):
    if not p and not q:
        return True
    elif not p or not q:
        return False
    elif p.data != q.data:
        return False
    else:
        return self.isSameTree(p.lchild, q.lchild) and self.isSameTree(p.rchild, q.rchild)

