from abc import ABCMeta, abstractmethod, abstractproperty
import sys


class IGraph(metaclass=ABCMeta):
    @abstractmethod
    def createGraph(self):
        '''创建图'''
        pass

    @abstractmethod
    def getVNum(self):
        '''返回图中的顶点数'''
        pass

    @abstractmethod
    def getENum(self):
        '''返回图中的边数'''
        pass

    @abstractmethod
    def getVex(self, i):
        '''返回位置为i的顶点值'''
        pass

    @abstractmethod
    def locateVex(self, x):
        '''返回值为x的顶点位置'''
        pass

    @abstractmethod
    def firstAdj(self, i):
        '''返回结点的第一个邻接点'''
        pass

    @abstractmethod
    def nextAdj(self, i, j):
        '''返回相对于j的下一个邻接点'''
        pass


class MGraph(IGraph):
    # 图类别静态常量
    GRAPHKIND_UDG = 'UDG'
    GRAPHKIND_DG = 'DG'
    GRAPHKIND_UDN = 'UDN'
    GRAPHKIND_DN = 'DN'

    def __init__(self, kind=None, vNum=0, eNum=0, v=None, e=None):
        self.kind = kind  # 图的种类
        self.vNum = vNum  # 图的顶点数
        self.eNum = eNum  # 图的边数
        self.v = v  # 顶点列表
        self.e = e  # 邻接矩阵

    def createUDG(self, vNum, eNum, v, e):
        self.vNum = vNum
        self.eNum = eNum
        self.v = [None] * vNum  # 构造顶点集
        for i in range(vNum):
            self.v[i] = v[i]
        self.e = [[0] * vNum] * vNum  # 构造边集
        for i in range(eNum):
            a, b = e[i]
        m, n = self.locateVex(a), self.locateVex(b)
        self.e[m][n] = self.e[n][m] = 1

    def createDG(self, vNum, eNum, v, e):
        self.vNum = vNum
        self.eNum = eNum
        self.v = [None] * vNum  # 构造顶点集
        for i in range(vNum):
            self.v[i] = v[i]
        self.e = [[0] * vNum] * vNum  # 构造边集
        for i in range(eNum):
            a, b = e[i]
        m, n = self.locateVex(a), self.locateVex(b)
        self.e[m][n] = 1

    def createUDN(self, vNum, eNum, v, e):
        self.vNum = vNum
        self.eNum = eNum
        self.v = [None] * vNum  # 构造顶点集
        for i in range(vNum):
            self.v[i] = v[i]
        self.e = [[sys.maxsize] * vNum] * vNum  # 初始化边集
        for i in range(eNum):
            a, b, w = e[i]
        m, n = self.locateVex(a), self.locateVex(b)
        self.e[m][n] = self.e[n][m] = w

    def createDN(self, vNum, eNum, v, e):
        self.vNum = vNum
        self.eNum = eNum
        self.v = [None] * vNum  # 构造顶点集
        for i in range(vNum):
            self.v[i] = v[i]
        self.e = [[sys.maxsize] * vNum] * vNum  # 初始化边集
        for i in range(eNum):
            a, b, w = e[i]
        m, n = self.locateVex(a), self.locateVex(b)
        self.e[m][n] = w

    def locateVex(self, x):
        for i in range(self.vNum):
            if self.v[i] == x:
                return i
        return -1

    def firstAdj(self, i):
        if i < 0 or i >= self.vNum:
            raise Exception("第%s个顶点不存在" % i)
        for j in range(self.vNum):
            if self.e[i][j] != 0 and self.e[i][j] < sys.maxsize:
                return j
        return -1

    def nextAdj(self, i, j):
        if j == self.vNum - 1:
            return -1
        for k in range(j + 1, self.vNum):
            if self.e[i][k] != 0 and self.e[i][k] < sys.maxsize:
                return k
        return -1


